package com.example.contextmenu; import android.graphics.Color; import android.os.Bundle; import android.view.ContextMenu; import android.view.MenuInflater; import android.view.MenuItem; import android.view.View; import android.widget.TextView; import android.widget.FrameLayout; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { FrameLayout mainLayout; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);mainLayout=findViewById(R.id.mainLayout);registerForContextMenu(findViewById(R.id.tvLongPress));} @Override public void onCreateContextMenu(ContextMenu menu,View view,ContextMenu.ContextMenuInfo info){super.onCreateContextMenu(menu,view,info);new MenuInflater(this).inflate(R.menu.context_menu,menu);} @Override public boolean onContextItemSelected(MenuItem item){if(item.getItemId()==R.id.colorRed){mainLayout.setBackgroundColor(Color.RED);return true;}if(item.getItemId()==R.id.colorGreen){mainLayout.setBackgroundColor(Color.GREEN);return true;}if(item.getItemId()==R.id.colorBlue){mainLayout.setBackgroundColor(Color.BLUE);return true;}return super.onContextItemSelected(item);}}
